<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { http } from "@/utils/http";
type DocumentItem = { id: string; resourceId?: string; title?: string; kind?: string; status?: string; author?: string; version?: string; currentRevisionId?: string; updatedAt?: string; publishedAt?: string };
const items = ref<DocumentItem[]>([]); const filtered = computed(() => items.value.filter(item => (!search.value || (item.title || item.id).toLowerCase().includes(search.value.toLowerCase())) && (kind.value === "all" || item.kind === kind.value) && (status.value === "all" || item.status === status.value))); const loading = ref(false); const saving = ref(false); const error = ref(""); const message = ref(""); const dialog = ref(false); const detail = ref<any>(false); const revisions = ref<any[]>([]); const fromRevision = ref<number | undefined>(); const toRevision = ref<number | undefined>(); const comparison = ref<any>(null); const comparisonLoading = ref(false); const restoreLoading = ref<Record<number, boolean>>({}); const publishLoading = ref<Record<number, boolean>>({}); const publishSlug = ref(""); const publication = ref<any>(null); const detailLoading = ref(false); const revisionsLoading = ref(false); const search = ref(""); const kind = ref("all"); const status = ref("all");
const form = ref({ title: "", kind: "DOCUMENT", locale: "zh-CN", content: "" });
async function load() { loading.value = true; error.value = ""; try { const result = await http.get<unknown, unknown>("/documents"); items.value = Array.isArray(result) ? result as DocumentItem[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "文档加载失败"; } finally { loading.value = false; } }
async function createDocument(type: string) { form.value.kind = type; if (!form.value.title.trim()) { error.value = "标题不能为空"; return; } saving.value = true; try { await http.post("/documents", { data: { ...form.value, title: form.value.title.trim() } }); dialog.value = false; form.value = { title: "", kind: "DOCUMENT", locale: "zh-CN", content: "" }; await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "文档创建失败"; } finally { saving.value = false; } }
async function loadRevisions(documentId: string) { revisionsLoading.value = true; try { const result = await http.get<unknown, unknown>(`/documents/${documentId}/revisions`); revisions.value = Array.isArray(result) ? result as any[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "版本列表加载失败"; } finally { revisionsLoading.value = false; } }
async function compareSelected() { if (!detail.value?.id || fromRevision.value === undefined || toRevision.value === undefined || fromRevision.value === toRevision.value) { error.value = "请选择两个不同的版本进行对比"; return; } comparisonLoading.value = true; error.value = ""; try { comparison.value = await http.get(`/documents/${detail.value.id}/revisions/compare`, { params: { fromRevision: fromRevision.value, toRevision: toRevision.value } }); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "版本差异加载失败"; } finally { comparisonLoading.value = false; } }
async function restoreRevision(revisionNumber: number) { if (!detail.value?.id || !window.confirm(`确认恢复版本 v${revisionNumber} 吗？这会创建一个新的当前版本。`)) return; restoreLoading.value[revisionNumber] = true; try { await http.post(`/documents/${detail.value.id}/revisions/${revisionNumber}/actions/restore`); message.value = `已恢复 v${revisionNumber}，并创建新的当前版本`; await loadRevisions(detail.value.id); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "版本恢复失败"; } finally { restoreLoading.value[revisionNumber] = false; } }
async function publishRevision(revisionNumber: number) { if (!detail.value?.id || !publishSlug.value.trim()) { error.value = "发布 slug 不能为空"; return; } publishLoading.value[revisionNumber] = true; try { publication.value = await http.post(`/documents/${detail.value.id}/actions/publish`, { data: { revisionNumber, slug: publishSlug.value.trim() } }); message.value = `v${revisionNumber} 已发布`; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "文档发布失败"; } finally { publishLoading.value[revisionNumber] = false; } }
async function unpublishDocument() { if (!detail.value?.id || !window.confirm("确认撤回当前发布吗？历史 Revision 不会删除。")) return; try { publication.value = await http.post(`/documents/${detail.value.id}/actions/unpublish`); message.value = "当前发布已撤回，历史 Revision 保留"; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "撤回发布失败"; } }
async function openDetail(row: DocumentItem) { detail.value = row; revisions.value = []; comparison.value = null; fromRevision.value = undefined; toRevision.value = undefined; detailLoading.value = true; try { const copy = await http.get<unknown, unknown>(`/documents/${row.id}/working-copy`); detail.value = { ...row, ...(copy as object) }; await loadRevisions(row.id); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "工作副本加载失败"; } finally { detailLoading.value = false; } }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start gap-4 mb-6"><div><h1 class="text-2xl font-semibold">文章与文档</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">统一管理草稿、发布状态、作者与版本。</p></div><div class="flex gap-2"><el-dropdown split-button type="primary" @click="dialog = true"><span>新建</span><template #dropdown><el-dropdown-menu><el-dropdown-item @click="dialog = true; form.kind = 'ARTICLE'">文章</el-dropdown-item><el-dropdown-item @click="dialog = true; form.kind = 'DOCUMENT'">文档</el-dropdown-item><el-dropdown-item @click="dialog = true; form.kind = 'NOTE'">公开笔记</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button :loading="loading" @click="load">刷新</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><div class="flex flex-wrap gap-3 mb-4"><el-input v-model="search" clearable placeholder="搜索标题" class="w-64"/><el-select v-model="kind" class="w-36"><el-option label="全部类型" value="all"/><el-option label="文章" value="ARTICLE"/><el-option label="文档" value="DOCUMENT"/><el-option label="公开笔记" value="NOTE"/></el-select><el-select v-model="status" class="w-36"><el-option label="全部状态" value="all"/><el-option label="草稿" value="DRAFT"/><el-option label="已发布" value="PUBLISHED"/><el-option label="已归档" value="ARCHIVED"/></el-select><el-input placeholder="作者 / Tag" class="w-40" disabled/><el-button @click="load">应用筛选</el-button></div><el-skeleton v-if="loading" :rows="8" animated/><el-card v-else shadow="never"><el-empty v-if="!filtered.length" description="暂无匹配文档"/><el-table v-else :data="filtered" stripe><el-table-column prop="title" label="标题" min-width="240"><template #default="{ row }"><el-button link type="primary" @click="openDetail(row)">{{ row.title || row.id }}</el-button></template></el-table-column><el-table-column prop="kind" label="类型" width="120"/><el-table-column prop="status" label="状态" width="120"/><el-table-column prop="author" label="作者" width="140"/><el-table-column prop="version" label="版本" width="100"/><el-table-column prop="updatedAt" label="更新时间" min-width="180"/><el-table-column prop="publishedAt" label="发布时间" min-width="180"/><el-table-column label="发布" width="90"><template #default="{ row }"><el-button link type="success" :loading="publishLoading[row.revisionNumber]" @click="publishRevision(row.revisionNumber)">发布</el-button></template></el-table-column><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link @click="openDetail(row)">详情</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" title="新建内容" width="560px"><el-form label-position="top"><el-form-item label="标题" required><el-input v-model="form.title" maxlength="256"/></el-form-item><el-form-item label="类型"><el-select v-model="form.kind" class="w-full"><el-option label="文章" value="ARTICLE"/><el-option label="文档" value="DOCUMENT"/><el-option label="公开笔记" value="NOTE"/></el-select></el-form-item><el-form-item label="语言"><el-input v-model="form.locale"/></el-form-item><el-form-item label="初始内容"><el-input v-model="form.content" type="textarea" :rows="6"/></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="createDocument(form.kind)">创建</el-button></template></el-dialog><el-drawer v-model="detail" title="文档工作副本" size="520px"><el-skeleton v-if="detailLoading" :rows="6" animated/><template v-else-if="detail"><el-descriptions :column="1" border><el-descriptions-item label="标题">{{ detail.title || '—' }}</el-descriptions-item><el-descriptions-item label="文档 ID">{{ detail.id }}</el-descriptions-item><el-descriptions-item label="类型">{{ detail.kind || '—' }}</el-descriptions-item><el-descriptions-item label="当前修订">{{ detail.currentRevisionId || '—' }}</el-descriptions-item><el-descriptions-item label="内容"><pre class="whitespace-pre-wrap">{{ detail.content || '—' }}</pre></el-descriptions-item></el-descriptions><el-divider/><div class="flex justify-between items-center mb-3"><span class="font-medium">版本列表</span><el-button size="small" :loading="revisionsLoading" @click="loadRevisions(detail.id)">刷新</el-button></div><div class="flex flex-wrap items-end gap-3 mb-3"><el-form-item label="基准版本"><el-select v-model="fromRevision" placeholder="选择版本" class="w-36"><el-option v-for="revision in revisions" :key="revision.revisionNumber + '-from'" :label="'v' + revision.revisionNumber" :value="revision.revisionNumber"/></el-select></el-form-item><el-form-item label="目标版本"><el-select v-model="toRevision" placeholder="选择版本" class="w-36"><el-option v-for="revision in revisions" :key="revision.revisionNumber + '-to'" :label="'v' + revision.revisionNumber" :value="revision.revisionNumber"/></el-select></el-form-item><el-input v-model="publishSlug" placeholder="发布 slug" class="w-44"/><el-button type="primary" :loading="comparisonLoading" @click="compareSelected">对比差异</el-button><el-button type="warning" @click="unpublishDocument">撤回发布</el-button></div><el-card v-if="comparison" shadow="never" class="mt-4"><template #header>v{{ comparison.fromRevisionNumber }} → v{{ comparison.toRevisionNumber }} 差异</template><div v-for="(line, index) in comparison.lines" :key="index" class="font-mono text-sm whitespace-pre-wrap px-2 py-1" :class="line.type === 'ADDED' ? 'bg-green-50 text-green-700' : line.type === 'REMOVED' ? 'bg-red-50 text-red-700' : 'text-gray-600'">{{ line.type === 'ADDED' ? '+ ' : line.type === 'REMOVED' ? '- ' : '  ' }}{{ line.content }}</div></el-card><el-empty v-if="!revisions.length" description="暂无已提交版本" :image-size="60"/><el-table v-else :data="revisions" size="small"><el-table-column prop="revisionNumber" label="版本" width="80"/><el-table-column prop="contentSchemaVersion" label="Schema" width="100"/><el-table-column prop="createdAt" label="创建时间" min-width="180"/><el-table-column prop="createdBy" label="创建者" min-width="220"/><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link type="warning" :loading="restoreLoading[row.revisionNumber]" @click="restoreRevision(row.revisionNumber)">恢复</el-button></template></el-table-column></el-table></template></el-drawer></main></template>
